import{z as o,x as d,o as e,c as s,q as t,j as l,D as E,d as A,s as r,S as n,b as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"订单簿动力学收束","description":"","frontmatter":{"title":"订单簿动力学收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/obd-map.md","filePath":"quant/obd-map.md","lastUpdated":1791413859000}'),u={name:"quant/obd-map.md"};function p(m,a,h,D,c,C){const i=d("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="订单簿动力学收束" tabindex="-1">订单簿动力学收束 <a class="header-anchor" href="#订单簿动力学收束" aria-label="Permalink to &quot;订单簿动力学收束&quot;">​</a></h1><div class="epigraph"><p>簿的动力学不是一条定律，是一叠互相约束的统计：速率方程、冲击律、噪声与季节，哪一条松了，别的都会替它说谎。</p><footer>—— 据 Bouchaud 等, Trades, Quotes and Prices, 2018；Cartea, Jaimungal and Penalva, Algorithmic and High-Frequency Trading, 2015 整理</footer></div><p><a href="/quant/obd-simulation-calibration">上一课</a>把校准的纪律收尾：分层对什么、按任务加权、开环与闭环分开。本课收束全课程：把十二课重排成一张地图，重申贯穿的口径，交还边界。做市与执行的深化课程会从这里接走速率方程与冲击函数，那是下一门课的事。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>十二课走完，要收的不是知识点清单，而是三条容易走散的主线。其一，动力学建模单元给了簿的「引擎」：队列的速率族、冲击的微观基础、订单流的状态空间、逆向选择的动态化——一条因果链，拆开用会断。其二，截面与时间单元给了「边界条件」：日内形状、竞价、共同因子、跨市场传导、高频噪声——引擎永远运行其上。其三，方法单元给了「检验协议」：微观事件研究与仿真校准——前面每一课的量都按这两套协议与数据对账。</p><p><span class="marginnote">直觉类比：把这门课想成造一台车——「引擎」是气缸与活塞（队列速率与冲击），「边界条件」是路况与天气（形状、竞价、共同性、噪声），「检验协议」是出厂前的台架测试。三样缺一，车都能往前推，但没人知道它能跑多远、什么时候散架。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法同样是收束而不新增：把十二课按「引擎—边界条件—检验协议」三层重排成读序地图，排序本身是论断——方法单元引用的每个量都产自前面的课，引擎的结论必须先于它的边界条件被读。地图之外只交两样东西：三条贯穿口径与三条边界，全是前课已立论命题的汇总。</p><h3 id="一张地图" tabindex="-1">一张地图 <a class="header-anchor" href="#一张地图" aria-label="Permalink to &quot;一张地图&quot;">​</a></h3><p>按读序重排：</p><ul><li><a href="/quant/obd-queue-dynamics">队列动力学的建模</a>：速率族与统计清单。</li><li><a href="/quant/obd-impact-microfoundations">价格冲击的微观基础</a>：耗散、恢复、残留，条件化在簿密度。</li><li><a href="/quant/obd-flow-statespace">订单流的状态空间表示</a>：多通道观测收成状态。</li><li><a href="/quant/obd-adverse-dynamic">逆向选择的动态版本</a>：价差是条件毒性的函数。</li><li><a href="/quant/obd-intraday-seasonality">日内季节性的稳定形态</a>：相位稳、幅度随体制伸缩。</li><li><a href="/quant/obd-auction-microstructure">竞价阶段的微观结构</a>：批量清算自成口径。</li><li><a href="/quant/obd-liquidity-common-factors">流动性的共同因子</a>：因子 + 载荷 + 特异。</li><li><a href="/quant/obd-crossmarket-linkage">跨市场联动与传导</a>：三条通道与时钟基准。</li><li><a href="/quant/obd-hf-vol-noise">高频波动率与微观噪声</a>：噪声是动力学的投影。</li><li><a href="/quant/obd-eventstudy-micro">事件研究的微观版本</a>：结果变量与推断的微观协议。</li><li><a href="/quant/obd-simulation-calibration">仿真校准：让模型对上数据</a>：分层校准、任务加权。</li></ul>',11)),(e(),l(n,null,{default:E(()=>[r(i,{id:"mermaid-85",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20ENG%5B%22%E5%8A%A8%E5%8A%9B%E5%AD%A6%E5%BB%BA%E6%A8%A1%EF%BC%9A%E5%BC%95%E6%93%8E%22%5D%0A%20%20%20%20Q%5B%22%E9%98%9F%E5%88%97%E9%80%9F%E7%8E%87%E6%97%8F%22%5D%20--%3E%20IMP%5B%22%E5%86%B2%E5%87%BB%E5%BE%AE%E8%A7%82%E5%9F%BA%E7%A1%80%22%5D%0A%20%20%20%20IMP%20--%3E%20SS%5B%22%E7%8A%B6%E6%80%81%E7%A9%BA%E9%97%B4%22%5D%0A%20%20%20%20SS%20--%3E%20ADV%5B%22%E5%8A%A8%E6%80%81%E9%80%86%E5%90%91%E9%80%89%E6%8B%A9%22%5D%0A%20%20end%0A%20%20subgraph%20BND%5B%22%E6%88%AA%E9%9D%A2%E4%B8%8E%E6%97%B6%E9%97%B4%EF%BC%9A%E8%BE%B9%E7%95%8C%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20%20%20SEA%5B%22%E6%97%A5%E5%86%85%E5%BD%A2%E7%8A%B6%22%5D%20--%3E%20AUC%5B%22%E7%AB%9E%E4%BB%B7%22%5D%0A%20%20%20%20AUC%20--%3E%20CF%5B%22%E5%85%B1%E5%90%8C%E5%9B%A0%E5%AD%90%22%5D%0A%20%20%20%20CF%20--%3E%20XM%5B%22%E8%B7%A8%E5%B8%82%E5%9C%BA%E4%BC%A0%E5%AF%BC%22%5D%0A%20%20%20%20XM%20--%3E%20NZ%5B%22%E9%AB%98%E9%A2%91%E5%99%AA%E5%A3%B0%22%5D%0A%20%20end%0A%20%20subgraph%20MTD%5B%22%E6%96%B9%E6%B3%95%EF%BC%9A%E6%A3%80%E9%AA%8C%E5%8D%8F%E8%AE%AE%22%5D%0A%20%20%20%20ES%5B%22%E5%BE%AE%E8%A7%82%E4%BA%8B%E4%BB%B6%E7%A0%94%E7%A9%B6%22%5D%20--%3E%20SIM%5B%22%E4%BB%BF%E7%9C%9F%E6%A0%A1%E5%87%86%22%5D%0A%20%20end%0A%20%20ENG%20--%3E%20BND%0A%20%20BND%20--%3E%20MTD%0A%20%20MTD%20--%3E%20NEXT%5B%22%E5%81%9A%E5%B8%82%E4%B8%8E%E6%89%A7%E8%A1%8C%E7%9A%84%E6%B7%B1%E5%8C%96%E8%AF%BE%E7%A8%8B%E6%8E%A5%E8%B5%B0%E5%BC%95%E6%93%8E%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[A("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"把十二课压成一个视角：簿的动力学 = 状态 × 速率 × 机制。状态可观测（队列、价差、滤波后的流）；速率是状态的条件函数（\\(\\lambda\\) 族、条件毒性、噪声水平）；机制是速率背后的行为与约束（拥挤税、信息不对称、做市资本、制度规则）。每课都在给这个三元组的一个分量装上测量与校验：一、二课装速率与机制，三、四课装在线估计，五到九课钉边界条件，十、十一课钉对账协议。这也解释了排序：引擎先于边界条件，边界条件先于方法——方法单元的每个协议引用的都是前面所有课的产出。",-1)),a[5]||(a[5]=B("p",null,"三元组的三个分量怎么互相接住、又怎么被对账协议兜底：",-1)),(e(),l(n,null,{default:E(()=>[r(i,{id:"mermaid-95",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E7%8A%B6%E6%80%81%3A%E9%98%9F%E5%88%97%2F%E4%BB%B7%E5%B7%AE%2F%E6%BB%A4%E6%B3%A2%E5%90%8E%E7%9A%84%E6%B5%81%22%5D%20--%3E%20RA%5B%22%E9%80%9F%E7%8E%87%3D%E7%8A%B6%E6%80%81%E7%9A%84%E6%9D%A1%E4%BB%B6%E5%87%BD%E6%95%B0%22%5D%0A%20%20ME%5B%22%E6%9C%BA%E5%88%B6%3A%E6%8B%A5%E6%8C%A4%2F%E4%BF%A1%E6%81%AF%2F%E5%81%9A%E5%B8%82%E8%B5%84%E6%9C%AC%2F%E5%88%B6%E5%BA%A6%22%5D%20--%3E%20RA%0A%20%20RA%20--%3E%20EX%5B%22%E8%AF%BB%E6%95%B0%3A%CE%BB%20%E6%97%8F%2F%E6%9D%A1%E4%BB%B6%E6%AF%92%E6%80%A7%2F%E5%99%AA%E5%A3%B0%E6%B0%B4%E5%B9%B3%22%5D%0A%20%20EX%20--%3E%20AC%5B%22%E5%AF%B9%E8%B4%A6%3A%E4%BA%8B%E4%BB%B6%E7%A0%94%E7%A9%B6%2B%E4%BB%BF%E7%9C%9F%E6%A0%A1%E5%87%86%22%5D%0A%20%20ST%20--%3E%20AC%0A%20%20AC%20--%3E%7C%22%E5%AF%B9%E4%B8%8D%E4%B8%8A%22%7C%20FIX%5B%22%E5%9B%9E%E5%A4%B4%E4%BF%AE%E6%9C%BA%E5%88%B6%E5%81%87%E8%AE%BE%2C%E8%80%8C%E9%9D%9E%E8%B0%83%E5%8F%82%E6%95%B0%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">数字实例：「状态 × 速率」的意思是：同样每秒来 2 笔主动单，簿上 10 档都厚与只剩 1 档薄是完全不同的紧张程度。速率方程写的不是常数「2」，而是「给定当前深度与价差，下一秒约来 2 笔」——状态一变，读数重新查表。</span></p><p><span class="marginnote">十二课的量互相条件化——冲击条件在簿密度、毒性条件在流状态、噪声条件在点差体制。脱离条件的「数值表」在这门课里不存在，任何抛开条件引用数字的用法都不是这门课的主张。</span></p><p>贯穿口径三条。统计清单先于模型：先写下要对上的统计与容差，再选生成器。条件化先于平均：冲击、毒性、噪声、季节处处是状态或体制的函数，全程平均是最后一项输入。闭环意识贯穿始终：报价改写来流、执行改写簿、仿真里自己的订单是状态的一部分——单向的统计关系在市场里是特例。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>收束课不新增机制，边界重申三条。可见簿：隐藏量、场外与内部化让每层估计带观测误差，补不进模型。约化：模型承诺「照这个状态行事的历史损失更小」，不承诺对手方的类型与意图。体制：全部系数——速率、冲击、噪声、形状、载荷——都带样本期烙印，制度变更日是共同的失效时刻。深钻层到此为止：主干的完整闭环加本课程的引擎与协议，构成下一阶段课程的全部前提。</p><p><span class="marginnote">为什么重要：三条边界破了都不会在原地报错——隐藏量让估计悄悄偏掉，约化承诺被当成意图去读，体制烙印让回测在制度变更日集体失效。跨课对账对不上号时，先查这三条，再怀疑参数。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一条主线：队列速率 → 冲击微观基础 → 状态空间 → 动态逆向选择，拆开用会断。</li><li>一层条件：日内形状、竞价口径、共同因子、跨市场通道、高频噪声，引擎运行其上。</li><li>一套协议：微观事件研究与仿真校准，把每个量与数据对账；权重来自下游任务。</li><li>三个口径：统计清单先于模型、条件化先于平均、闭环意识贯穿始终。</li><li>边界三条：可见簿、约化模型、体制烙印——制度变更日是共同的失效时刻。</li><li>出处：Bouchaud 等, <em>Trades, Quotes and Prices</em>, 2018；Cartea, Jaimungal and Penalva, <em>Algorithmic and High-Frequency Trading</em>, 2015；Harris, <em>Trading and Exchanges</em>, 2003。</li></ul>',8))])}const F=o(u,[["render",p]]);export{f as __pageData,F as default};
